-- [S6] ECHO facility rows for the 18 registry IDs: neighbourhood (PCT_MINORITY, density, county FIPS), programs, compliance history, counts
SELECT TO_VARCHAR(FRS_ID) AS REG, FACILITY_NAME, CITY, STATE, COUNTY, FIPS_CODE, PCT_MINORITY, POPULATION_DENSITY, HAS_AIR_PROGRAM AS AIR, HAS_WATER_PROGRAM AS WAT, HAS_HAZWASTE_PROGRAM AS RCRA, HAS_TOXIC_RELEASE_PROGRAM AS TRI, HAS_GREENHOUSE_GAS_PROGRAM AS GHG,
  COMPLIANCE_STATUS, QUARTERS_WITH_NONCOMPLIANCE AS QNC, THREE_YR_COMPLIANCE_HISTORY AS HIST, TOTAL_INSPECTION_COUNT AS INSP, DATE_LAST_INSPECTION, INFORMAL_ACTION_COUNT AS INF, FORMAL_ACTION_COUNT AS FORMAL, DATE_LAST_FORMAL_ACTION, LAST_PENALTY_AMT_ALLOCATED, DATE_LAST_PENALTY, TRI_ON_SITE_RELEASES, IS_MAJOR_FACILITY, IS_ACTIVE
FROM LIBRARY_MARTS.ENVIRONMENT.ENVIRONMENT__FED_EPA_ECHO
WHERE TO_VARCHAR(FRS_ID) IN ('110017404548','110005972821','110041204265','110020497121','110000448043','110000448472','110000596793','110030484107','110022409883','110037424533','110000606504','110031127126','110040499449','110070005201','110030917603','110029535171','110000615503','110001505602') ORDER BY STATE, FACILITY_NAME
